function renderMonthly(){const readings={};data.server.forEach(r=>{const d=Number(r[0].split('/')[0]);if(!readings[d])readings[d]=r});const names=['Minggu','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'];$('#monthlyTemperatureRows').innerHTML=Array.from({length:30},(_,i)=>{const d=i+1,date=new Date(2026,10,i+1),weekend=[0,6].includes(date.getDay()),r=readings[d];return `<tr class="${weekend&&!r?'weekend':''} ${r?'has-reading':''}"><td>${d}</td><td>${String(d).padStart(2,'0')}/11/2026</td><td>${names[date.getDay()]}, ${d} November 2026</td>${r?`<td>${r[2]}</td><td>${r[3]}</td><td>${r[4]}</td><td>✓</td><td></td><td>${paraf(r[6])}</td>`:'<td></td><td></td><td></td><td></td><td></td><td></td><td></td>'}</tr>`}).join('');$('#monthlyWorkRows').innerHTML=data.work.map(r=>`<tr><td>Nov26</td>${r.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('');const bad=data.server.filter(r=>r[5]!=='Normal');$('#monthlyNotes').innerHTML=bad.length?bad.map(r=>`<li>${esc(r[0])} · ${esc(r[1])}: ${esc(r[5])}</li>`).join(''):'<li>Seluruh hasil pengecekan dalam kondisi normal.</li><li>—</li><li>—</li>'}
function show(p){$$('.page').forEach(x=>x.classList.toggle('active-page',x.id===p));$$('.nav[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===p));const n={dashboard:['OVERVIEW','Selamat pagi, Rifqi'],attendance:['OPERASIONAL','Absensi'],work:['OPERASIONAL','Laporan pekerjaan'],server:['INFRASTRUKTUR','Pengecekan server'],reimburse:['KEUANGAN','Reimbursement'],request:['PENGADAAN','Pengajuan barang'],monthly:['REKAP','Laporan bulanan'],settings:['SISTEM','Pengaturan']};$('#crumb').textContent=n[p][0];$('#pageTitle').textContent=n[p][1];scrollTo(0,0)}function toast(t){$('#toast').textContent=t;$('#toast').classList.remove('hidden');setTimeout(()=>$('#toast').classList.add('hidden'),2600)}
function printDoc(m){if(m==='monthly'){print();return}const rooms={'server-lantai5':'Lantai 5','server-r610':'R.610 Kaca'},room=rooms[m]||'',module=room?'server':m,labels={attendance:'Absensi',work:'Laporan Pekerjaan',server:'Pengecekan Suhu Ruang Server',reimburse:'Surat Permohonan Reimbursement',request:'Pengajuan Barang'};if(!labels[module])return toast('Pilih modul laporan yang ingin dicetak terlebih dahulu.');const source=$('#'+module)?.querySelector('table'),w=open('','_blank','width=900,height=700');if(!w)return toast('Izinkan pop-up browser untuk mencetak laporan.');const copy=source.cloneNode(true);copy.querySelectorAll('tbody tr').forEach(tr=>{if(room&&!tr.children[1]?.textContent.includes(room))tr.remove()});copy.querySelectorAll('tr').forEach(tr=>{tr.lastElementChild?.remove();if(['reimburse','request'].includes(module))tr.children[5]?.remove()});let body=copy.outerHTML;if(module==='reimburse')body=`<p>Kepada Yth.<br><b>Manajer terkait</b></p><p>Berikut rincian pengajuan reimbursement periode November 2026.</p>${body}<p>Demikian pengajuan ini dibuat untuk dapat diproses.</p><p style="text-align:right;margin-top:42px">Pemohon,<br><br><br><b>Rifqi Muhammad Athallah</b></p>`;const title=room?`${labels[module]} — ${room}`:labels[module];w.document.write(`<!doctype html><title>${title}</title><style>body{font-family:Arial;color:#111;margin:34px}header{border-bottom:2px solid #172b4d;padding-bottom:12px;margin-bottom:22px}h1{font-size:21px;margin:0}p{font-size:13px;line-height:1.5}table{border-collapse:collapse;width:100%;font-size:11px}th,td{border:1px solid #555;padding:8px;text-align:left;vertical-align:top}th{background:#e9edf2}img{max-height:30px;max-width:70px}@page{size:A4 portrait;margin:14mm}</style><header><h1>${title}</h1><p>Periode November 2026<br>Dicetak: ${new Date().toLocaleDateString('id-ID')}</p></header>${body}`);w.document.close();w.onafterprint=()=>setTimeout(()=>w.close(),150);setTimeout(()=>w.print(),250)}
function input(l,t,v=''){return `<label>${l}<input type="${t}" value="${esc(v)}" required></label>`}function toInput(v=''){if(/^\d{2}\/\d{2}\/\d{4}$/.test(v)){const[a,b,c]=v.split('/');return `${c}-${b}-${a}`}const m=v.match(/(\d{1,2})\s+(\w+)\s+(\d{4})/);if(!m)return '';const mo={Jan:0,Feb:1,Mar:2,Apr:3,Mei:4,Jun:5,Jul:6,Agu:7,Sep:8,Okt:9,Nov:10,Des:11}[m[2].slice(0,3)]??10;return `${m[3]}-${String(mo+1).padStart(2,'0')}-${m[1].padStart(2,'0')}`}function human(v){if(!v)return '';const[y,m,d]=v.split('-');return `${d} ${['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep','Okt','Nov','Des'][Number(m)-1]} ${y}`}
function fields(m,r=[]){const choices=(list,value='')=>`<select required>${list.map(x=>`<option value="${x}" ${x===value?'selected':''}>${x}</option>`).join('')}</select>`;if(m==='server')return input('Tanggal','date',toInput(r[0]))+`<label>Ruangan${choices(['Lantai 5','R.610 Kaca'],r[1])}</label>`+input('Jam','time',r[2])+input('Suhu (°C)','number',String(r[3]||'').replace('°C',''))+input('Kelembaban (%)','number',String(r[4]||'').replace('%',''))+`<label>Upload paraf (PNG/JPG)<input id="signatureFile" type="file" accept="image/png,image/jpeg"></label>`;if(m==='work')return input('Tanggal','date',toInput(r[0]))+`<label>Kategori${choices(['Server','Network','Access Control','IP-PBX','CCTV','Lain-lain'],r[1])}</label>`+input('Judul','text',r[2])+`<label>Detail permasalahan<textarea rows="3" required>${esc(r[3]||'')}</textarea></label><label>Solusi<textarea rows="3" required>${esc(r[4]||'')}</textarea></label>`;if(m==='attendance')return input('Nama karyawan','text',r[0])+input('Tanggal','date',toInput(r[1]))+input('Jam masuk','time',r[2])+input('Jam pulang','time',r[3]);if(m==='reimburse')return input('Tanggal','date',toInput(r[1]))+input('Pemohon','text',r[2])+input('Keterangan','text',r[3])+input('Total biaya','number',String(r[4]||'').replace(/\D/g,''))+`<label>Status${choices(['Menunggu','Disetujui','Ditolak'],r[5]||'Menunggu')}</label>`;return input('Tanggal','date',toInput(r[1]))+input('Nama barang','text',r[2])+input('Jumlah','text',r[3])+input('Keperluan','text',r[4])+`<label>Status${choices(['Menunggu','Disetujui','Ditolak'],r[5]||'Menunggu')}</label>`}
function modal(m,i=null){$('#modalTitle').textContent=(i===null?'Buat ':'Edit ')+({attendance:'absensi',work:'laporan pekerjaan',server:'pemeriksaan suhu server',reimburse:'pengajuan reimbursement',request:'pengajuan barang'}[m]);$('#formFields').innerHTML=fields(m,i===null?[]:data[m][i]);$('#modal').dataset.module=m;$('#modal').dataset.index=i===null?'':i;$('#modal').classList.remove('hidden')}
$('#loginBtn').onclick=()=>{if($('#email').value&&$('#password').value){$('#login').classList.add('hidden');$('#app').classList.remove('hidden');sessionStorage.opsAuth='1'}else toast('Masukkan email dan kata sandi.')};if(sessionStorage.opsAuth){$('#login').classList.add('hidden');$('#app').classList.remove('hidden')}$('#logout').onclick=()=>{sessionStorage.removeItem('opsAuth');location.reload()};$$('[data-page]').forEach(b=>b.onclick=()=>show(b.dataset.page));$$('[data-new]').forEach(b=>b.onclick=()=>{show(b.dataset.new);setTimeout(()=>modal(b.dataset.new),100)});$$('.add').forEach(b=>b.onclick=()=>modal(b.closest('.report-page').dataset.module));$('.close').onclick=()=>$('#modal').classList.add('hidden');$('#modal').onclick=e=>{if(e.target===$('#modal'))$('#modal').classList.add('hidden')};$('#saveEntry').onclick=()=>{const m=$('#modal').dataset.module,i=$('#modal').dataset.index,v=$$('#formFields input:not([type=file]),#formFields textarea,#formFields select').map(x=>x.value);if(v.some(x=>!x))return toast('Lengkapi semua data terlebih dahulu.');let r;if(m==='work')r=[human(v[0]),...v.slice(1)];else if(m==='server')r=[v[0].split('-').reverse().join('/'),v[1],v[2],v[3]+'°C',v[4]+'%','Normal',uploadedParaf||(i===''?'Rifqi Muhammad Athallah':data[m][i][6])];else if(m==='attendance')r=[v[0],human(v[1]),v[2],v[3],'Hadir'];else if(m==='reimburse')r=[i===''?'RB-2026-'+(33+data.reimburse.length):data[m][i][0],human(v[0]),v[1],v[2],'Rp'+Number(v[3]).toLocaleString('id-ID'),v[4]];else r=[i===''?'PB-2026-'+(20+data.request.length):data[m][i][0],human(v[0]),v[1],v[2],v[3],v[4]];i===''?data[m].unshift(r):data[m][Number(i)]=r;uploadedParaf='';render();$('#modal').classList.add('hidden');toast(i===''?'Laporan berhasil disimpan.':'Perubahan tersimpan; rekap bulanan diperbarui.');};$$('.import input').forEach(i=>i.onchange=e=>e.target.files[0]&&toast('File dipilih. Hubungkan parser Excel di backend untuk impor produksi.'));$('#printAll').onclick=()=>printDoc($('.report-page.active-page')?.id);$('#monthlyPrint').onclick=()=>printDoc('monthly');document.addEventListener('change',e=>{if(e.target.id==='signatureFile'&&e.target.files[0]){const reader=new FileReader();reader.onload=()=>{uploadedParaf=reader.result;toast('Paraf siap dipakai pada laporan.');};reader.readAsDataURL(e.target.files[0])}});document.addEventListener('click',e=>{const ed=e.target.closest('[data-edit]');if(ed){const[m,i]=ed.dataset.edit.split(':');return modal(m,Number(i))}const p=e.target.closest('[data-print],.print-row');if(p)return printDoc(p.dataset.print||p.closest('.report-page')?.id);const tab=e.target.closest('[data-month-view]');if(tab){$$('[data-month-view]').forEach(x=>x.classList.toggle('active',x===tab));$('#monthlyTemperature').classList.toggle('hidden',tab.dataset.monthView!=='temperature');$('#monthlyWork').classList.toggle('hidden',tab.dataset.monthView!=='worklog')}});$$('[data-copy]').forEach(b=>b.onclick=()=>{navigator.clipboard?.writeText(b.dataset.copy);toast('Panduan konfigurasi: gunakan environment variable '+b.dataset.copy+' di deployment.')});render();
function buildMonthlyDocument(){const tabs=$('.monthly-tabs');if(!tabs||$('#monthlyFull'))return;tabs.insertAdjacentHTML('beforeend','<button data-month-view="full">Laporan lengkap</button>');const html=`<div id="monthlyFull" class="monthly-sheet hidden"><div class="sheet-title"><h2 contenteditable="true">LAPORAN BULANAN</h2><p contenteditable="true">NOVEMBER 2026</p></div><section class="monthly-intro" contenteditable="true"><b>Pendahuluan</b><p>Saya, Rifqi Muhammad Athallah, telah melaksanakan pekerjaan dan pengecekan operasional selama bulan ini. Berikut laporan pekerjaan dan hasil pengecekan yang telah dilakukan.</p></section><section><h3>Index Pekerjaan</h3><table class="monthly-table"><thead><tr><th>No.</th><th>Bulan</th><th>Tanggal</th><th>Kategori</th><th>Judul / Kegiatan</th><th>Detail Permasalahan</th><th>Solusi / Hasil</th></tr></thead><tbody>${data.work.map((r,i)=>`<tr><td>${i+1}</td><td>Nov26</td>${r.map(x=>`<td contenteditable="true">${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></section><section class="monthly-intro"><b>Catatan Bulanan</b><p contenteditable="true">Seluruh pekerjaan telah dicatat sesuai pelaksanaan. Tambahkan kesimpulan atau kendala bulan ini di sini.</p></section><div class="monthly-notes"><div><b>Disusun oleh</b><span contenteditable="true">Rifqi Muhammad Athallah</span><small>Tgl: ................................</small></div><div><b>Approval</b><span contenteditable="true">Yuna Sukmana</span><small>Tgl: ................................</small></div></div></div>`;$('#monthlyWork').insertAdjacentHTML('afterend',html);document.querySelector('[data-month-view="full"]').onclick=e=>{e.preventDefault();$$('[data-month-view]').forEach(x=>x.classList.toggle('active',x===e.currentTarget));$('#monthlyTemperature').classList.add('hidden');$('#monthlyWork').classList.add('hidden');$('#monthlyFull').classList.remove('hidden')}}
